const fs = await import('node:fs');
const skill = fs.readFileSync('F:/codex/modbus/clarify-and-optimize-prompt/SKILL.md', 'utf8');
const meta = fs.readFileSync('F:/codex/modbus/clarify-and-optimize-prompt/agents/openai.yaml', 'utf8');
const checks = [
  ['frontmatter name', skill.startsWith('---\nname: clarify-and-optimize-prompt\ndescription: ')],
  ['Chinese title', skill.includes('# 需求澄清与提示词优化')],
  ['final format section', skill.includes('## 最终输出格式')],
  ['openai display name', meta.includes('display_name: "需求澄清与提示词优化"')],
  ['default prompt skill token', meta.includes('Use $clarify-and-optimize-prompt')]
];
nodeRepl.write(JSON.stringify(checks, null, 2));
